<?php
$pdo = db();
$categories = ['Utilities','Repairs and maintenance','Learning materials','Transport','Food and boarding','Examinations','Administration','Communication','Security','Other'];
$statuses = ['Submitted','Approved','Rejected','Paid'];
$year = filter_var($_GET['year'] ?? date('Y'), FILTER_VALIDATE_INT);
if (!$year || $year < 2000 || $year > 2100) $year = (int)date('Y');
$statusFilter = (string)($_GET['status'] ?? '');
if (!in_array($statusFilter, $statuses, true)) $statusFilter = '';
$categoryFilter = (string)($_GET['category'] ?? '');
if (!in_array($categoryFilter, $categories, true)) $categoryFilter = '';
$canSubmit = in_array($user['role'], ['Administrator','Head','Bursar'], true);
$canReview = in_array($user['role'], ['Administrator','Head'], true);
$canPay = in_array($user['role'], ['Administrator','Bursar'], true);
$summaryStmt = $pdo->prepare("SELECT currency,SUM(status='Paid') paid_count,SUM(CASE WHEN status='Paid' THEN amount ELSE 0 END) paid_total,SUM(status='Submitted') submitted_count,SUM(status='Approved') approved_count FROM school_expenses WHERE expense_date BETWEEN :start AND :end GROUP BY currency");
$summaryStmt->execute(['start'=>$year.'-01-01','end'=>$year.'-12-31']);
$summary = ['USD'=>['paid_count'=>0,'paid_total'=>0.0,'submitted_count'=>0,'approved_count'=>0],'ZiG'=>['paid_count'=>0,'paid_total'=>0.0,'submitted_count'=>0,'approved_count'=>0]];
foreach ($summaryStmt->fetchAll() as $row) $summary[$row['currency']] = $row;
$where = ['e.expense_date BETWEEN :start AND :end'];
$params = ['start'=>$year.'-01-01','end'=>$year.'-12-31'];
if ($statusFilter !== '') { $where[]='e.status=:status'; $params['status']=$statusFilter; }
if ($categoryFilter !== '') { $where[]='e.category=:category'; $params['category']=$categoryFilter; }
$stmt = $pdo->prepare('SELECT e.*,creator.full_name creator_name,reviewer.full_name reviewer_name,payer.full_name payer_name FROM school_expenses e LEFT JOIN users creator ON creator.id=e.created_by LEFT JOIN users reviewer ON reviewer.id=e.reviewed_by LEFT JOIN users payer ON payer.id=e.paid_by WHERE '.implode(' AND ',$where).' ORDER BY e.expense_date DESC,e.id DESC LIMIT 250');
$stmt->execute($params);
$expenses = $stmt->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">SCHOOL FINANCE</div><h1>Operating expenses</h1><p class="subheading">Submit, approve and record payment of school operating costs. USD and ZiG are tracked separately.</p></div></div>
<div class="finance-summary"><article class="panel"><span>USD paid in <?= (int)$year ?></span><b>$<?= number_format((float)$summary['USD']['paid_total'],2) ?></b></article><article class="panel"><span>ZiG paid in <?= (int)$year ?></span><b>ZiG <?= number_format((float)$summary['ZiG']['paid_total'],2) ?></b></article><article class="panel"><span>Awaiting review</span><b><?= (int)$summary['USD']['submitted_count']+(int)$summary['ZiG']['submitted_count'] ?></b></article><article class="panel"><span>Approved, awaiting payment</span><b><?= (int)$summary['USD']['approved_count']+(int)$summary['ZiG']['approved_count'] ?></b></article></div>
<?php if ($canSubmit): ?><section class="panel settings-panel"><h2>Submit an expense</h2><p>Every submission needs an approval before payment can be recorded. The person who submits it cannot approve or pay it.</p><form method="post" action="actions/expense_submit.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><label>Category<select name="category" required><?php foreach($categories as $category): ?><option><?= h($category) ?></option><?php endforeach; ?></select></label><label>Supplier / payee<input name="supplier" maxlength="180" required></label><label>Description<input name="description" maxlength="500" required placeholder="What was purchased or service provided?"></label><label>Invoice / voucher reference <span class="optional">Optional</span><input name="invoice_reference" maxlength="100"></label><label>Amount<input type="number" name="amount" min="0.01" max="999999999999.99" step="0.01" required></label><label>Currency<select name="currency"><option>USD</option><option>ZiG</option></select></label><label>Expense date<input type="date" name="expense_date" max="<?= h(date('Y-m-d')) ?>" value="<?= h(date('Y-m-d')) ?>" required></label><button class="primary-button">Submit for approval</button></form></section><?php endif; ?>
<section class="panel learners-panel"><form class="list-toolbar" method="get"><input type="hidden" name="page" value="expenses"><div class="toolbar-right"><label>Year <select class="select-control" name="year"><?php for($y=(int)date('Y');$y>=((int)date('Y')-8);$y--): ?><option value="<?= $y ?>" <?= $year===$y?'selected':'' ?>><?= $y ?></option><?php endfor; ?></select></label><select class="select-control" name="status"><option value="">All statuses</option><?php foreach($statuses as $status): ?><option <?= $statusFilter===$status?'selected':'' ?>><?= h($status) ?></option><?php endforeach; ?></select><select class="select-control" name="category"><option value="">All categories</option><?php foreach($categories as $category): ?><option <?= $categoryFilter===$category?'selected':'' ?>><?= h($category) ?></option><?php endforeach; ?></select><button class="outline-button">Filter</button></div></form><div class="panel-heading"><div><h2>Expense register</h2><p>Showing up to 250 records for <?= (int)$year ?> · payment history is retained</p></div><a class="outline-button" href="actions/expense_export.php?<?= h(http_build_query(["year"=>$year,"status"=>$statusFilter,"category"=>$categoryFilter])) ?>">Download CSV</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date / supplier</th><th>Category / details</th><th>Amount</th><th>Status</th><th>Submitted / review</th><th>Payment</th></tr></thead><tbody><?php foreach($expenses as $expense): ?><tr><td><?= h(date('d M Y',strtotime($expense['expense_date']))) ?><br><b><?= h($expense['supplier']) ?></b><?php if($expense['invoice_reference']): ?><small class="muted-cell">Ref: <?= h($expense['invoice_reference']) ?></small><?php endif; ?></td><td><?= h($expense['category']) ?><br><?= h($expense['description']) ?><?php if($expense['review_note']): ?><details><summary>Review note</summary><p><?= nl2br(h($expense['review_note'])) ?></p></details><?php endif; ?></td><td><?= h($expense['currency']) ?> <?= number_format((float)$expense['amount'],2) ?></td><td><span class="status-pill"><?= h($expense['status']) ?></span></td><td><?= h($expense['creator_name']??'Former staff') ?><small class="muted-cell"><?= h(date('d M Y H:i',strtotime($expense['created_at']))) ?></small><?php if($expense['reviewer_name']): ?><small class="muted-cell">Reviewed by <?= h($expense['reviewer_name']) ?> · <?= h(date('d M Y H:i',strtotime($expense['reviewed_at']))) ?></small><?php endif; ?></td><td><?php if($expense['status']==='Paid'): ?><?= h($expense['payment_method']) ?><?= $expense['payment_reference']?' · '.h($expense['payment_reference']):'' ?><small class="muted-cell">Paid by <?= h($expense['payer_name']??'Former staff') ?> · <?= h(date('d M Y H:i',strtotime($expense['paid_at']))) ?></small><?php else: ?>—<?php endif; ?>
<?php if($canReview && $expense['status']==='Submitted' && (int)$expense['created_by']!==(int)$user['id']): ?><details><summary>Review submission</summary><form method="post" action="actions/expense_transition.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="expense_id" value="<?= (int)$expense['id'] ?>"><input type="hidden" name="operation" value="review"><label>Decision<select name="decision"><option value="Approved">Approve</option><option value="Rejected">Reject</option></select></label><label>Review note <span class="optional">Required when rejecting</span><input name="review_note" maxlength="500"></label><button class="outline-button">Save review</button></form></details><?php endif; ?>
<?php if($canPay && $expense['status']==='Approved' && (int)$expense['reviewed_by']!==(int)$user['id']): ?><details><summary>Record payment</summary><form method="post" action="actions/expense_transition.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="expense_id" value="<?= (int)$expense['id'] ?>"><input type="hidden" name="operation" value="pay"><label>Method<select name="payment_method" required><?php foreach(['Cash','EcoCash','Bank transfer','Swipe','Other'] as $method): ?><option><?= h($method) ?></option><?php endforeach; ?></select></label><label>Payment reference <span class="optional">Optional</span><input name="payment_reference" maxlength="100"></label><button class="primary-button">Confirm paid</button></form></details><?php endif; ?></td></tr><?php endforeach; if(!$expenses): ?><tr><td colspan="6" class="empty-cell">No expenses match these filters.</td></tr><?php endif; ?></tbody></table></div></section>
